,p_report_body_template=>'<ul class="amc-NProfiles amc-NProfiles--#STYLE#{case COLUMNS/}{when 2/} amc-NProfiles--cols2{when 3/} amc-NProfiles--cols3{when 4/} amc-NProfiles--cols4{otherwise/}{endcase/}">#APEX$ROWS#</ul>'
,p_report_row_template=>'<li class="amc-NProfiles-item">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-profile.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-profile.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Pick a Style, then map Name (required) and any of Role, Image URL or Initials, Bio, Status, up to three stats, Link URL and Link Label, Email, Phone, Location, Organisation and Reference. Empty settings are left out. Tilt Holo ID needs the plug-in JavaScript file for its pointer tilt and works without it as a static card. Every hover effect also runs on keyboard focus, and all motion stops when the user asks the system for reduced motion.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
